-- PYTH BOMB: question bank, batch 4 — 228 EASY general-knowledge questions (Claude, 2026-10-16)
-- Run in Supabase SQL Editor. Safe to run more than once (duplicate question text is skipped).
-- Check the list in perguntas-lote4-para-conferir.txt first.
--
-- Step 1 also allows new category names (music, tv, geography, history, science, food, games,
-- tech). This does NOT change the game: today every verified question goes into the same deck.
-- It only prepares the "host picks a category" idea for later.
-- Answers are compared in lowercase, without accents or punctuation (so "Beyoncé" = "beyonce").

alter table public.questions drop constraint if exists questions_category_check;
alter table public.questions add constraint questions_category_check
  check (category in ('pyth', 'community', 'general', 'sports', 'movies', 'fun', 'music', 'tv', 'geography', 'history', 'science', 'food', 'games', 'tech'));

on conflict do nothing;

-- check: how many batch-4 questions are in the bank now (should be 228)
select count(*) as batch4_questions from public.questions where source_reference = 'Claude batch 4 (easy)';

